// =====================================================================
//  WELT 4 – DER HAFEN – GERÜST
//  Informatik LK · Online-IDE · Algo Quest · Level 4.1 bis 4.6
//
//  Hinter dem Labyrinth liegt der Hafen. Kisten werden gestapelt,
//  Schiffe warten in einer Schlange auf ihren Liegeplatz, und der
//  Hafenmeister fuehrt eine Ladeliste, die waechst und schrumpft. Fuer
//  das Dungeon-Spiel baust du daraus Spielmodule: Rueckgaengig/
//  Wiederholen (Stapel), die Zugreihenfolge im Kampf (Schlange) und das
//  Inventar (dynamische Reihung).
//
//  ANLEITUNG:
//  0. BIBLIOTHEK EINSCHALTEN (einmal pro Workspace, sonst kennt die IDE
//     Stack, Queue und DynArray nicht):
//     Workspace in der Liste links mit der RECHTEN Maustaste anklicken
//     -> "Einstellungen" -> Haekchen bei "Niedersachsen" setzen -> OK.
//     Danach sind die Abitur-Klassen Stack, Queue, DynArray und BinTree
//     da (die Java-Klassen Stack, ArrayList, LinkedList ... sind dann
//     ausgeblendet).
//
//  1. Du arbeitest NUR im Abschnitt "DEIN TEIL". Ueber jeder Methode
//     stehen ihre Signatur in Abi-Notation und eine kurze Beschreibung.
//     Ersetze die Zeilen "// TODO Level 4.x" und die vorlaeufigen
//     return-Anweisungen durch deine Loesung. In Zugbuch und Initiative
//     sind die Attribute schon vorgegeben - die Konstruktoren schreibst
//     du selbst. Die Klassen Knoten und MeinStapel (Level 4.6, Experte)
//     schreibst du komplett selbst nach den Klassenkarten.
//
//  2. Tests starten: Oeffne den Reiter "Testrunner" und klicke auf den
//     gruenen Dreieckspfeil neben einer Testklasse (alle Tests dieses
//     Levels) oder neben einem einzelnen Test. Gruen = bestanden,
//     rot = noch nicht bestanden. Lies bei roten Tests die Meldung!
//     Beginnt sie mit "LAUFZEITFEHLER", ist dein Programm abgestuerzt
//     (z. B. pop auf leerem Stapel) - der Hinweis sagt dir, wo du suchen
//     musst. Haengt der Testrunner, hast du eine Endlosschleife (z. B.
//     beim Rotieren einer Schlange ohne Zaehler): Programm anhalten,
//     Schleifenbedingung pruefen.
//
//  3. Die Level und ihre Testklassen:
//
//      Level  DS         Klasse(n)                  Testklasse
//      -------------------------------------------------------------------
//      4.1    24         Hafen                      L41StapelSchlangeTest
//                        Stack und Queue benutzen, Leerabfragen
//      4.2    25 (Kuer)  Zugbuch, Initiative        L42SpielmoduleTest
//                        Rueckgaengig/Wiederholen, Zugreihenfolge
//      4.3    26         Unveraendert               L43UnveraendertTest
//                        Hilfsstapel, Hilfsschlange, zurueckschichten
//      4.4    27         Ladeliste                  L44LadelisteTest
//                        DynArray: sortiert einfuegen, loeschen
//      4.5    28         Umformen                   L45UmformenTest
//                        ADT in ADT umformen, Klammern, Postfix
//      4.6    29 (Kuer)  Expertenpfad, Knoten,      L46ExpertenpfadTest
//                        MeinStapel
//                        Flood-Fill ohne Rekursion, eigener Stapel
//
//     In jedem Level gibt es drei Stufen. Du erkennst sie am Anfang des
//     Testnamens:
//          basis_...         Basis
//          erweiterung_...   Erweiterung
//          experte_...       Experte
//     Eine Stufe ist geschafft, wenn ALLE Tests mit diesem Anfang gruen
//     sind. Am Anfang ist noch kein Test gruen.
//
//  4. INFOKASTEN: CASTEN BEI DEN ABITUR-KLASSEN
//     Stack, Queue und DynArray speichern alles als Object. Was du
//     herausholst, musst du in den richtigen Typ umwandeln (casten):
//         Kiste k = (Kiste) s.pop();              // Stapel vom Inhaltstyp Kiste
//         int x = (Integer) q.dequeue();          // Schlange vom Inhaltstyp Ganzzahl
//         char c = (Character) s.pop();           // Stapel vom Inhaltstyp Zeichen
//         String name = (String) q.head();        // Schlange vom Inhaltstyp Zeichenkette
//         Kiste k = (Kiste) d.getItem(i);         // dynamische Reihung vom Inhaltstyp Kiste
//     Hineinlegen geht ohne Cast: s.push(5); q.enqueue("Moewe");
//     d.append(k); - Zahlen und Zeichen werden automatisch verpackt.
//     Den Variablentyp schreibst du OHNE spitze Klammern:
//         Stack s = new Stack();     Queue q = new Queue();
//         DynArray d = new DynArray();
//     Zahlen vergleichen: erst casten, dann rechnen bzw. vergleichen:
//         int x = (Integer) s.pop();   if (x > max) { ... }
//     Kisten vergleichen: ueber die Getter, Namen mit equals:
//         Kiste k = (Kiste) q.head();  if (k.getName().equals(name)) { ... }
//     Ohne Cast meldet die IDE einen Fehler ("Object kann nicht in int
//     umgewandelt werden"). Ein FALSCHER Cast (z. B. (Integer) auf eine
//     Kiste) fuehrt erst beim Ausfuehren zum Laufzeitfehler.
//
//  5. ABI-CHECK FUER JEDE METHODE: "Leer? Index?" (+ "unveraendert?")
//     - Leer?  top(), pop(), head() und dequeue() auf einer LEEREN
//       Struktur sind ein Laufzeitfehler (IllegalStateException). Vorher
//       IMMER mit isEmpty() pruefen - die Tests pruefen leere Strukturen!
//     - Index? getItem, setItem und delete nur mit 0 <= i < getLength(),
//       insertAt mit 0 <= i <= getLength() (insertAt(getLength(), x)
//       haengt hinten an). Wer in einer Vorwaerts-Schleife mit delete
//       loescht, rutscht ueber das naechste Element hinweg!
//     - unveraendert?  Steht "UNVERAENDERT" ueber einer Methode, muss die
//       uebergebene Struktur am Ende wieder GENAU so aussehen wie vorher:
//       dieselben Objekte in derselben Reihenfolge. Muster: alles in
//       einen Hilfsstapel bzw. eine Hilfsschlange umschichten und danach
//       zurueckschichten. Die Tests pruefen das genau.
//
//  6. FREISCHALTEN von Level 4.6 (Experte): Die Tests fuer Knoten und
//     MeinStapel und ein kleiner Teil des Hauptprogramms sind
//     auskommentiert, damit das Geruest ohne diese Klassen kompiliert.
//     Jeder Block beginnt mit einer Zeile "/* LEVEL-4.6-START" und endet
//     mit einer Zeile "LEVEL-4.6-ENDE */". Zum Freischalten loeschst du
//     genau diese beiden Zeilen (in der Testklasse L46ExpertenpfadTest
//     und im Hauptprogramm). Schalte erst frei, wenn Knoten und
//     MeinStapel kompilieren.
//
//  7. VORGEGEBEN (nicht veraendern): die Klasse Kiste, die Hilfsklassen
//     Testhilfe und Kartenbuch sowie in Expertenpfad das Attribut spur
//     und die Methode merke. Die Testklassen darfst du NICHT veraendern
//     (ausser dem Freischalten in Schritt 6) - sonst zaehlt der Test nicht.
//     Du glaubst, ein Test ist falsch? Melde ihn deiner Lehrkraft (Bug-Meldung).
//
//  8. Mit dem gruenen Startknopf oben laeuft das Hauptprogramm ganz unten
//     (ein Tag im Hafen mit Konsolenausgabe).
//
//  SPIELREGELN (wie im Abitur):
//  - Stapel (Stack): LIFO - nur oben ablegen (push), oben nachsehen
//    (top) und oben wegnehmen (pop).
//  - Schlange (Queue): FIFO - hinten anstellen (enqueue), vorne
//    nachsehen (head) und vorne entnehmen (dequeue).
//  - Dynamische Reihung (DynArray): Zugriff ueber den Index ab 0,
//    Laenge mit getLength(); Einfuegen und Loeschen verschieben die
//    Elemente dahinter.
//  - Zeichenketten IMMER mit equals vergleichen, nie mit ==.
//  - Jede Methode mit Rueckgabetyp braucht in JEDEM Fall ein return.
// =====================================================================


// ---------------------------------------------------------------------
//  GERÜST – hier nichts veraendern
// ---------------------------------------------------------------------
//  Kiste:      die Fracht im Hafen (wird in allen Leveln benutzt).
//  Testhilfe:  baut Stapel/Schlangen/Reihungen fuer die Tests und
//              liest sie aus, OHNE sie zu veraendern. Die Tests zeigen
//              dir damit in der Meldung den ganzen Inhalt, z. B.
//              "[erwartet: [Erz (5 kg), Holz (3 kg)], tatsaechlich: ...]".
//              Stapel werden von OBEN nach unten, Schlangen von VORNE
//              nach hinten angezeigt. Ausserdem: die Standard-Ladung
//              (sechs Kisten) und die Meldung bei Laufzeitfehlern.
//  Kartenbuch: die Dungeon-Karten aus Welt 3 als 2D-Reihungen (Level 4.6).
//  Du darfst alle drei Klassen auch im Hauptprogramm benutzen.
// ---------------------------------------------------------------------

//  Klassenkarte (Notation wie im Abitur):
//      Kiste
//      ------------------------------------------------
//      - name: Zeichenkette
//      - gewicht: Ganzzahl                     // in kg
//      ------------------------------------------------
//      + c Kiste(name: Zeichenkette, gewicht: Ganzzahl)
//      + getName(): Zeichenkette
//      + getGewicht(): Ganzzahl
//      + beschreibung(): Zeichenkette          // z. B. "Erz (5 kg)"

class Kiste {

    private String name;
    private int gewicht;

    public Kiste(String name, int gewicht) {
        this.name = name;
        this.gewicht = gewicht;
    }

    public String getName() {
        return name;
    }

    public int getGewicht() {
        return gewicht;
    }

    public String beschreibung() {
        return name + " (" + gewicht + " kg)";
    }
}


class Testhilfe {

    // ----- Strukturen bauen -----

    // Stapel aus Ganzzahlen: werte[0] zuerst, der letzte Wert liegt oben.
    public static Stack zahlenStapel(int[] werte) {
        Stack s = new Stack();
        for (int i = 0; i < werte.length; i++) {
            s.push(werte[i]);
        }
        return s;
    }

    // Schlange aus Ganzzahlen: werte[0] steht vorne.
    public static Queue zahlenSchlange(int[] werte) {
        Queue q = new Queue();
        for (int i = 0; i < werte.length; i++) {
            q.enqueue(werte[i]);
        }
        return q;
    }

    // Schlange aus Zeichenketten: namen[0] steht vorne.
    public static Queue namenSchlange(String[] namen) {
        Queue q = new Queue();
        for (int i = 0; i < namen.length; i++) {
            q.enqueue(namen[i]);
        }
        return q;
    }

    // Stapel aus Kisten: kisten[0] liegt unten, die letzte Kiste oben.
    public static Stack kistenStapel(Kiste[] kisten) {
        Stack s = new Stack();
        for (int i = 0; i < kisten.length; i++) {
            s.push(kisten[i]);
        }
        return s;
    }

    // Schlange aus Kisten: kisten[0] steht vorne.
    public static Queue kistenSchlange(Kiste[] kisten) {
        Queue q = new Queue();
        for (int i = 0; i < kisten.length; i++) {
            q.enqueue(kisten[i]);
        }
        return q;
    }

    // Dynamische Reihung aus Kisten in derselben Reihenfolge.
    public static DynArray kistenReihung(Kiste[] kisten) {
        DynArray d = new DynArray();
        for (int i = 0; i < kisten.length; i++) {
            d.append(kisten[i]);
        }
        return d;
    }

    // ----- Inhalt auslesen, OHNE die Struktur zu veraendern -----

    // Inhalt eines Stapels von oben nach unten. s ist danach wieder genau
    // wie vorher (dieselben Objekte, dieselbe Reihenfolge).
    public static DynArray stapelInhalt(Stack s) {
        if (s == null) {
            return null;
        }
        DynArray d = new DynArray();
        Stack hilf = new Stack();
        while (!s.isEmpty()) {
            Object o = s.pop();
            d.append(o);
            hilf.push(o);
        }
        while (!hilf.isEmpty()) {
            s.push(hilf.pop());
        }
        return d;
    }

    // Inhalt einer Schlange von vorne nach hinten. q ist danach wieder
    // genau wie vorher.
    public static DynArray schlangeInhalt(Queue q) {
        if (q == null) {
            return null;
        }
        DynArray d = new DynArray();
        while (!q.isEmpty()) {
            d.append(q.dequeue());
        }
        for (int i = 0; i < d.getLength(); i++) {
            q.enqueue(d.getItem(i));
        }
        return d;
    }

    // ----- Texte fuer die Meldungen -----

    // Zahlen oder Zeichenketten als Text, z. B. "[4, 8, 15]".
    public static String text(DynArray d) {
        if (d == null) {
            return "null";
        }
        String t = "[";
        for (int i = 0; i < d.getLength(); i++) {
            if (i > 0) {
                t = t + ", ";
            }
            t = t + d.getItem(i);
        }
        return t + "]";
    }

    // Kisten als Text, z. B. "[Erz (5 kg), Holz (3 kg)]".
    public static String kistenText(DynArray d) {
        if (d == null) {
            return "null";
        }
        String t = "[";
        for (int i = 0; i < d.getLength(); i++) {
            if (i > 0) {
                t = t + ", ";
            }
            Kiste k = (Kiste) d.getItem(i);
            t = t + k.beschreibung();
        }
        return t + "]";
    }

    public static String stapelText(Stack s) {
        return text(stapelInhalt(s));
    }

    public static String schlangeText(Queue q) {
        return text(schlangeInhalt(q));
    }

    public static String kistenStapelText(Stack s) {
        return kistenText(stapelInhalt(s));
    }

    public static String kistenSchlangeText(Queue q) {
        return kistenText(schlangeInhalt(q));
    }

    // ----- Vergleich: dieselben Objekte in derselben Reihenfolge? -----

    public static boolean dieselben(DynArray a, DynArray b) {
        if (a == null || b == null) {
            return false;
        }
        if (a.getLength() != b.getLength()) {
            return false;
        }
        for (int i = 0; i < a.getLength(); i++) {
            if (a.getItem(i) != b.getItem(i)) {
                return false;
            }
        }
        return true;
    }

    // Eine Kiste als Text (auch null), z. B. "Erz (5 kg)".
    public static String kisteText(Kiste k) {
        if (k == null) {
            return "null";
        }
        return k.beschreibung();
    }

    // ----- Die Standard-Ladung des Hafens (fuer Tests, AB und Hauptprogramm) -----

    // Liefert bei JEDEM Aufruf sechs NEUE Kisten:
    //     Holz (3 kg), Erz (5 kg), Gold (8 kg), Salz (3 kg), Tuch (8 kg), Wein (6 kg)
    // Gesamtgewicht 33 kg, Durchschnitt 5,5 kg.
    public static Kiste[] ladung() {
        Kiste[] k = new Kiste[6];
        k[0] = new Kiste("Holz", 3);
        k[1] = new Kiste("Erz", 5);
        k[2] = new Kiste("Gold", 8);
        k[3] = new Kiste("Salz", 3);
        k[4] = new Kiste("Tuch", 8);
        k[5] = new Kiste("Wein", 6);
        return k;
    }

    // ----- Laufzeitfehler in einem Test verstaendlich melden -----

    // Die Tests fangen Laufzeitfehler (Exceptions) ab und melden sie mit
    // einem Hinweis. In einer richtigen Loesung tritt NIE ein Laufzeitfehler
    // auf - auch nicht bei leeren Strukturen!
    public static void laufzeitfehler(RuntimeException e) {
        String meldung = " (Meldung der IDE: " + e.getMessage() + ")";
        try {
            throw e;
        } catch (IllegalStateException x) {
            fail("LAUFZEITFEHLER: top, pop, head oder dequeue auf einer LEEREN Struktur - Leerabfrage mit isEmpty() vergessen?" + meldung);
        } catch (IndexOutOfBoundsException x) {
            fail("LAUFZEITFEHLER: Index ausserhalb - bei DynArray gilt 0 <= i < getLength() (insertAt: i <= getLength()). Schleifengrenze pruefen! Geloescht und danach i erhoeht?" + meldung);
        } catch (IllegalArgumentException x) {
            fail("LAUFZEITFEHLER: null in Stack, Queue oder DynArray gelegt - push, enqueue, append, insertAt und setItem verbieten null." + meldung);
        } catch (ClassCastException x) {
            fail("LAUFZEITFEHLER: falscher Cast - passt (Kiste), (Integer), (String) bzw. (Character) zum Inhaltstyp der Struktur?" + meldung);
        } catch (NullPointerException x) {
            fail("LAUFZEITFEHLER: Zugriff auf null - Attribut im Konstruktor nicht erzeugt (new Stack() ...)? Liefert eine Methode noch null?" + meldung);
        } catch (RuntimeException x) {
            fail("LAUFZEITFEHLER" + meldung);
        }
    }

    // ----- Sonstiges -----

    // Neue Zeichenkette mit demselben Inhalt wie s (Zeichen fuer Zeichen
    // zusammengesetzt). Damit pruefen die Tests, dass du Zeichenketten mit
    // equals vergleichst und nicht mit ==.
    public static String kopie(String s) {
        String t = "";
        for (int i = 0; i < s.length(); i++) {
            t = t + s.charAt(i);
        }
        return t;
    }

    // Pseudo-Zufallszahl (linearer Kongruenzgenerator): liefert aus x
    // die naechste Zahl zwischen 0 und 65536 - immer dieselbe Folge.
    public static int naechsteZufallszahl(int x) {
        return (x * 75 + 74) % 65537;
    }

    // 2D-Reihung als Text: Zeilen mit "\n" getrennt.
    public static String kartenText(char[][] karte) {
        if (karte == null) {
            return "null";
        }
        String t = "";
        for (int z = 0; z < karte.length; z++) {
            if (z > 0) {
                t = t + "\n";
            }
            for (int s = 0; s < karte[z].length; s++) {
                t = t + karte[z][s];
            }
        }
        return t;
    }

    // Zeilen als Text (wie kartenText), fuer erwartete Karten.
    public static String zeilenText(String[] zeilen) {
        String t = "";
        for (int i = 0; i < zeilen.length; i++) {
            if (i > 0) {
                t = t + "\n";
            }
            t = t + zeilen[i];
        }
        return t;
    }
}


// Die Testkarten aus Welt 3 als Reihung von Reihung von Zeichen:
// karte[z][s] = Zeile z, Spalte s. '#' Wand, '.' frei, 'S' Start, 'Z' Ziel.
// Jeder Aufruf liefert eine NEUE Karte (frisch vernebelt).
class Kartenbuch {

    // Baut aus Textzeilen eine 2D-Reihung: karte[z][s] = zeilen[z].charAt(s).
    public static char[][] karte(String[] zeilen) {
        char[][] k = new char[zeilen.length][zeilen[0].length()];
        for (int z = 0; z < zeilen.length; z++) {
            for (int s = 0; s < zeilen[z].length(); s++) {
                k[z][s] = zeilen[z].charAt(s);
            }
        }
        return k;
    }

    // Die offene Hoehle (5 x 7), Start (1, 1), Ziel (3, 5).
    public static char[][] hoehle() {
        String[] zeilen = {
            "#######",
            "#S....#",
            "#..#..#",
            "#....Z#",
            "#######"
        };
        return karte(zeilen);
    }

    // Das Labyrinth (9 x 9), Start (1, 1), Ziel (5, 7); die Kammer unten
    // rechts ist nur UEBER ECK mit dem Gang verbunden.
    public static char[][] labyrinth() {
        String[] zeilen = {
            "#########",
            "#S#...#.#",
            "#.#.#.#.#",
            "#...#...#",
            "#.###.#.#",
            "#...#.#Z#",
            "###.##.##",
            "#...#...#",
            "#########"
        };
        return karte(zeilen);
    }

    // Der Kerker (6 x 8), Start (1, 1), Ziel (2, 5) in einer eigenen Kammer.
    public static char[][] kerker() {
        String[] zeilen = {
            "########",
            "#S..#..#",
            "#.#.#Z.#",
            "#...####",
            "#.#....#",
            "########"
        };
        return karte(zeilen);
    }

    // Die Lichtung (3 x 4) OHNE Randmauer, Start (1, 1), Ziel (2, 3).
    public static char[][] lichtung() {
        String[] zeilen = {
            "..#.",
            ".S..",
            "#..Z"
        };
        return karte(zeilen);
    }
}


// ---------------------------------------------------------------------
//  DEIN TEIL – hier arbeitest du!
// ---------------------------------------------------------------------
//  Ueber jeder Methode steht ihre Signatur in Abi-Notation:
//      name(p: Typ, q: Typ): Rueckgabetyp
//  Neu in Welt 4 (Klassen der Bibliothek "Niedersachsen"):
//      Stapel vom Inhaltstyp Kiste                  Stack
//      Schlange vom Inhaltstyp Ganzzahl             Queue
//      dynamische Reihung vom Inhaltstyp Kiste      DynArray
//
//  Die Schnittstellen (wie in den Ergaenzenden Hinweisen zum Abitur):
//      Stack    : c Stack(), isEmpty(): Wahrheitswert, push(x): nichts,
//                 top(): Inhaltstyp, pop(): Inhaltstyp
//      Queue    : c Queue(), isEmpty(): Wahrheitswert, enqueue(x): nichts,
//                 head(): Inhaltstyp, dequeue(): Inhaltstyp
//      DynArray : c DynArray(), isEmpty(): Wahrheitswert,
//                 getItem(i): Inhaltstyp, append(x): nichts,
//                 insertAt(i, x): nichts, setItem(i, x): nichts,
//                 delete(i): nichts, getLength(): Ganzzahl
//
//  Muster "UNVERAENDERT" (Beispiel: Stapel durchlaufen):
//
//      Stack hilf = new Stack();
//      while (!s.isEmpty()) {             // Leer? -> erst pruefen
//          Kiste k = (Kiste) s.pop();     // Cast!
//          // ... k auswerten ...
//          hilf.push(k);                  // DIESELBE Kiste aufheben
//      }
//      while (!hilf.isEmpty()) {
//          s.push(hilf.pop());            // zurueckschichten
//      }
// ---------------------------------------------------------------------

// ============= Level 4.1 – Stapel und Schlange (DS 24) ==============
//  Alle Methoden sind static: Aufruf mit Klassenname, z. B.
//  Hafen.leeren(s).

class Hafen {

    // ===================== Stufe BASIS =====================

    // stapleAuf(werte: Reihung von Ganzzahl): Stapel vom Inhaltstyp Ganzzahl
    // Erzeugt einen NEUEN Stapel und legt die Werte darauf: werte[0]
    // zuerst, der letzte Wert liegt oben. {4, 8, 15} -> oben 15, unten 4.
    public static Stack stapleAuf(int[] werte) {
        // TODO Level 4.1 · Basis
        return null;
    }

    // obersterWert(s: Stapel vom Inhaltstyp Ganzzahl): Ganzzahl
    // Liefert den obersten Wert, OHNE ihn zu entfernen (top, nicht pop).
    // Leerer Stapel -> -1.
    public static int obersterWert(Stack s) {
        // TODO Level 4.1 · Basis
        return -1;
    }

    // leeren(s: Stapel): Ganzzahl
    // Entnimmt ALLE Elemente und gibt zurueck, wie viele es waren.
    // Danach ist s leer. Leerer Stapel -> 0.
    public static int leeren(Stack s) {
        // TODO Level 4.1 · Basis
        return -1;
    }


    // ================== Stufe ERWEITERUNG ==================

    // warteschlange(namen: Reihung von Zeichenkette): Schlange vom Inhaltstyp Zeichenkette
    // Erzeugt eine NEUE Schlange: namen[0] stellt sich zuerst an (steht
    // vorne), der letzte Name steht hinten.
    public static Queue warteschlange(String[] namen) {
        // TODO Level 4.1 · Erweiterung
        return null;
    }

    // naechster(q: Schlange vom Inhaltstyp Zeichenkette): Zeichenkette
    // Entnimmt den vordersten Namen und gibt ihn zurueck.
    // Leere Schlange -> "".
    public static String naechster(Queue q) {
        // TODO Level 4.1 · Erweiterung
        return "?";
    }

