    @Test
    public void erweiterung_klammernOk_richtig() {
        try {
            assertTrue(Umformen.klammernOk("(a+b)*[c-{d}]"), "'(a+b)*[c-{d}]' ist richtig geklammert (andere Zeichen ignorieren)");
            assertTrue(Umformen.klammernOk("{[()()]}"), "'{[()()]}' ist richtig geklammert");
            assertTrue(Umformen.klammernOk("()[]{}"), "'()[]{}' ist richtig geklammert");
            assertTrue(Umformen.klammernOk("Hafen"), "'Hafen' enthaelt keine Klammern -> true");
            assertTrue(Umformen.klammernOk(""), "Die leere Zeichenkette ist richtig geklammert -> true");
        } catch (RuntimeException e) {
            Testhilfe.laufzeitfehler(e);
        }
    }

    @Test
    public void erweiterung_klammernOk_falsch() {
        try {
            assertTrue(Umformen.klammernOk("[x]"), "'[x]' ist richtig geklammert");
            assertFalse(Umformen.klammernOk("(]"), "'(]': ] passt nicht zu ( -> false");
            assertFalse(Umformen.klammernOk("([)]"), "'([)]': ) passt nicht zur zuletzt geoeffneten [ -> false");
            assertFalse(Umformen.klammernOk("(()"), "'(()': am Ende ist noch eine Klammer offen -> false (Stapel am Ende leer?)");
            assertFalse(Umformen.klammernOk("())"), "'())': zu viele schliessende Klammern -> false (Leerabfrage vor pop!)");
            assertFalse(Umformen.klammernOk("}"), "'}': schliessende Klammer ohne oeffnende -> false (Leerabfrage vor pop!)");
            assertFalse(Umformen.klammernOk(")("), "')(': falsche Reihenfolge -> false");
        } catch (RuntimeException e) {
            Testhilfe.laufzeitfehler(e);
        }
    }

